// Extract the invoice data from AI Agent output
const invoiceData = $input.item.json.output || {};

// CRITICAL: Preserve the filename from the input item
// The merge node should have preserved it in $input.item.json.fileName
const originalFileName = $input.item.json.fileName || 'unknown_invoice.pdf';

// GSTIN Validation Function
function validateGSTIN(gstin) {
  if (!gstin) return { valid: false, message: 'GSTIN is missing' };

  // Indian GSTIN format: 15 characters
  // Format: 2 digits (state) + 10 chars (PAN) + 1 char (entity) + 1 char (Z by default) + 1 check digit
  const gstinRegex = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;

  if (!gstinRegex.test(gstin)) {
    return { valid: false, message: 'GSTIN format is invalid' };
  }

  return { valid: true, message: 'GSTIN is valid' };
}

// Date Validation Function
function validateDate(dateStr) {
  if (!dateStr) return { valid: false, message: 'Date is missing' };

  // Check if date is in YYYY-MM-DD format
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(dateStr)) {
    return { valid: false, message: 'Date format should be YYYY-MM-DD' };
  }

  const date = new Date(dateStr);
  if (isNaN(date.getTime())) {
    return { valid: false, message: 'Invalid date value' };
  }

  return { valid: true, message: 'Date is valid' };
}

// Financial Validation Function
function validateFinancials(financial) {
  const issues = [];

  // Check if critical amounts are present
  if (!financial.Total_Invoice_Amount) {
    issues.push('Total Invoice Amount is missing');
  }

  // Validate GST calculation: CGST + SGST OR IGST should equal Total_GST
  const cgst = parseFloat(financial.CGST) || 0;
  const sgst = parseFloat(financial.SGST) || 0;
  const igst = parseFloat(financial.IGST) || 0;
  const totalGst = parseFloat(financial.Total_GST) || 0;

  const calculatedGst = (cgst + sgst) || igst;
  const gstDifference = Math.abs(calculatedGst - totalGst);

  if (gstDifference > 0.01) {
    issues.push(`GST calculation mismatch: CGST(${cgst}) + SGST(${sgst}) or IGST(${igst}) ≠ Total GST(${totalGst})`);
  }

  // Validate total: Subtotal + Total_GST should equal Total_Invoice_Amount
  const subtotal = parseFloat(financial.Subtotal) || 0;
  const totalAmount = parseFloat(financial.Total_Invoice_Amount) || 0;
  const calculatedTotal = subtotal + totalGst;
  const totalDifference = Math.abs(calculatedTotal - totalAmount);

  if (totalDifference > 0.01) {
    issues.push(`Total calculation mismatch: Subtotal(${subtotal}) + Total GST(${totalGst}) ≠ Total Amount(${totalAmount})`);
  }

  return issues;
}

// Ensure Invoice_Metadata exists
if (!invoiceData.Invoice_Metadata) invoiceData.Invoice_Metadata = {};

// Perform validations
const gstinValidation = validateGSTIN(invoiceData.Invoice_Metadata.Vendor_GSTIN);
const dateValidation = validateDate(invoiceData.Invoice_Metadata.Invoice_Date);
const financialIssues = validateFinancials(invoiceData.Financial_Summary || {});

// Check for missing critical fields
const missingFields = [];
if (!invoiceData.Invoice_Metadata.Invoice_Number) missingFields.push('Invoice Number');
if (!invoiceData.Invoice_Metadata.Invoice_Date) missingFields.push('Invoice Date');
if (!invoiceData.Invoice_Metadata.Vendor_GSTIN) missingFields.push('Vendor GSTIN');
if (!invoiceData.Financial_Summary?.Total_Invoice_Amount) missingFields.push('Total Invoice Amount');

// Determine overall status
let validationStatus = 'OK';
let validationIssues = [];

if (!gstinValidation.valid) {
  validationIssues.push(gstinValidation.message);
  validationStatus = 'Error';
}

if (!dateValidation.valid) {
  validationIssues.push(dateValidation.message);
  validationStatus = 'Error';
}

if (financialIssues.length > 0) {
  validationIssues.push(...financialIssues);
  validationStatus = 'Error';
}

if (missingFields.length > 0) {
  validationIssues.push(`Missing critical fields: ${missingFields.join(', ')}`);
  if (validationStatus === 'OK') validationStatus = 'Warning';
}

// Update the invoice data with validation results
invoiceData.Invoice_Metadata.Status = validationStatus;
invoiceData.Invoice_Metadata.Issue_Description = validationIssues.length > 0 
  ? validationIssues.join('; ') 
  : 'All validations passed';

// Save filename to metadata AND root for later nodes
invoiceData.Invoice_Metadata.Invoice_File_Name = originalFileName;
invoiceData.fileName = originalFileName;

// Add validation metadata
invoiceData.Validation = {
  GSTIN_Valid: gstinValidation.valid,
  Date_Valid: dateValidation.valid,
  Financial_Valid: financialIssues.length === 0,
  Missing_Fields: missingFields,
  Validation_Timestamp: new Date().toISOString()
};

return { json: invoiceData };

// Normalize binary field names from Invoice_File or Invoice_File_0, Invoice_File_1, etc.
// to a consistent 'data' field name for processing
// Process all items and create separate items for each file
// Preserve original binary data and prepare for URL generation

const items = $input.all();
const outputItems = [];

for (const item of items) {
  // Get all binary data keys
  const binaryKeys = Object.keys(item.binary || {});

  // Find all keys that start with 'Invoice_File'
  const invoiceFileKeys = binaryKeys.filter(key => key.startsWith('Invoice_File'));

  if (invoiceFileKeys.length > 0) {
    // Create a separate item for each invoice file
    for (const invoiceFileKey of invoiceFileKeys) {
      const originalBinary = item.binary[invoiceFileKey];

      // Preserve original binary data and add normalized 'data' field
      const normalizedBinary = {
        data: originalBinary,
        [invoiceFileKey]: originalBinary  // Keep original key as well
      };

      // Create new item with normalized binary field and enhanced JSON fields
      outputItems.push({
        json: {
          ...item.json,
          fileName: originalBinary.fileName || originalBinary.filename || 'unknown',
          mimeType: originalBinary.mimeType || originalBinary.mimetype || 'unknown',
          fileSize: originalBinary.fileSize || originalBinary.size || 0,
          publicUrl: null
        },
        binary: normalizedBinary
      });
    }
  } else {
    // No Invoice_File binary found, return item as-is
    outputItems.push(item);
  }
}

return outputItems;

